-- Adapta el examen CCDV-F (Claude Certified Developer – Foundations) a la guía v1.1 (vigente desde el 7/12/2026).
-- Cambios: simulacro de 70 preguntas / 120 min (minisimulacro 20 / 35 min), nombres y pesos de dominio nuevos,
-- 34 preguntas pasan al dominio que les corresponde en la v1.1, 68 preguntas fuera del temario nuevo
-- se desactivan (no se borran: se conserva el historial de cada usuario), las 3 preguntas de ejemplo de la v1.0
-- pasan a ser del banco y se añaden las 3 de ejemplo de la v1.1 más 65 preguntas nuevas.
-- Resultado: 500 preguntas activas -> D1 85, D2 100, D3 40, D4 50, D5 60, D6 75, D7 40, D8 50.
-- Ejecutar en Supabase: SQL Editor > New query > pegar > Run. Se puede ejecutar varias veces.
do $do$
declare
  v_exam uuid;
  v_plan jsonb := $plan${"moves": [{"stem": "Un desarrollador usa la misma conversación de Claude Code durante tres días para tareas sin relación y nota respuestas más lentas y menos precisas. ¿Qué práctica de session hygiene aplica?", "domain": "D3"}, {"stem": "Un equipo quiere usar Claude Code para refactorizar a gran escala un monolito de 400.000 líneas. ¿Qué enfoque es el más seguro?", "domain": "D3"}, {"stem": "¿Qué DOS prácticas de session hygiene mejoran la fiabilidad de Claude Code en un repositorio grande? (Elige 2)", "domain": "D3"}, {"stem": "Un desarrollador pide a Claude Code una refactorización amplia y, en la misma sesión, después de compactar dos veces, Claude empieza a reintroducir un patrón que se había descartado al principio. ¿Qué práctica lo evita mejor?", "domain": "D3"}, {"stem": "Un equipo va a refactorizar un módulo heredado sin tests con ayuda de Claude Code. ¿Qué paso previo reduce más el riesgo de cambiar el comportamiento sin darse cuenta?", "domain": "D3"}, {"stem": "Un esquema de salida para facturas tiene 40 campos opcionales y el modelo a veces rellena campos con valores inventados. ¿Qué cambio de schema design ayuda más?", "domain": "D6"}, {"stem": "Un esquema de salida para extraer pedidos tiene el campo \"cantidad\" como string. Aparecen valores como \"3\", \"tres\", \"3 uds\" y \"aprox. 3\". ¿Qué cambio de diseño de esquema es el más eficaz?", "domain": "D6"}, {"stem": "Un esquema de salida para clasificar incidencias tiene 25 categorías planas y el modelo confunde a menudo categorías parecidas. ¿Qué cambio de diseño suele mejorar más la fiabilidad?", "domain": "D6"}, {"stem": "Un equipo diseña la salida estructurada de un asistente que propone acciones al CRM. Hoy el esquema es un único campo de texto libre \"accion\" que el backend interpreta. ¿Qué rediseño de esquema reduce más los errores de interpretación?", "domain": "D6"}, {"stem": "Un asistente legal debe indicar de qué parte exacta del documento sale cada afirmación para que un abogado lo verifique. ¿Qué capacidad de la API encaja mejor?", "domain": "D6"}, {"stem": "Un sistema de RAG recupera 30 fragmentos por consulta y la calidad baja respecto a usar 8. ¿Qué explicación y medida son las más razonables?", "domain": "D6"}, {"stem": "Un LLM responde con seguridad una cifra que no aparece en los documentos proporcionados. ¿Qué medida reduce mejor este comportamiento?", "domain": "D6"}, {"stem": "Un prompt incluye un único ejemplo de entrada y salida antes de la tarea. ¿Qué técnica es?", "domain": "D6"}, {"stem": "Para una tarea de extracción con formato muy específico, un prompt zero-shot falla en casos con formatos de fecha poco habituales. ¿Qué técnica de prompting suele dar la mejora más directa?", "domain": "D6"}, {"stem": "Un single-shot (un ejemplo) hace que el modelo copie palabras del ejemplo en respuestas que no tienen nada que ver. ¿Qué ajuste es el más adecuado?", "domain": "D6"}, {"stem": "Un equipo quiere evitar que un cambio en el prompt rompa producción sin que nadie lo note. ¿Qué DOS prácticas de ciclo de vida lo consiguen? (Elige 2)", "domain": "D4"}, {"stem": "Un equipo mide la calidad de su asistente solo antes de cada despliegue. Tras tres meses sin cambios de código, las quejas aumentan. ¿Qué carencia del ciclo de vida explica mejor que no lo detectaran antes?", "domain": "D4"}, {"stem": "Un equipo quiere definir criterios de aceptación para un clasificador de reclamaciones, pero no tiene ningún ejemplo etiquetado. ¿Qué debe incluir la fase de requisitos?", "domain": "D4"}, {"stem": "Al definir requisitos de un clasificador, negocio pide un 98% de acierto. El equipo mide la línea base humana y descubre que dos expertos coinciden solo en el 91% de los casos. ¿Qué implica para el requisito?", "domain": "D4"}, {"stem": "Un equipo compara dos modelos con una sola ejecución de 20 casos: A acierta 17 y B 16. ¿Qué conclusión es correcta?", "domain": "D4"}, {"stem": "Un equipo observa que su clasificador acierta el 94% en una ejecución y el 91% en otra con los mismos casos, prompt y modelo. ¿Qué conclusión y práctica son correctas?", "domain": "D4"}, {"stem": "¿Qué DOS ventajas aporta usar el SDK oficial frente a llamar a la API REST a mano? (Elige 2)", "domain": "D2"}, {"stem": "Una aplicación Python llama a la API REST con requests y gestiona a mano los reintentos, el parseo del stream SSE y los tipos de respuesta. ¿Qué ventaja concreta obtendría pasando al SDK oficial?", "domain": "D2"}, {"stem": "Al configurar el SDK en un servicio, el equipo pone max_retries a 0 y añade su propio reintento con backoff y jitter, respetando retry-after. ¿Qué es cierto?", "domain": "D2"}, {"stem": "¿Qué DOS situaciones justifican usar WebSockets entre tu frontend y tu backend en una aplicación con Claude? (Elige 2)", "domain": "D2"}, {"stem": "Un backend reenvía al navegador el stream de Claude a través de SSE. Detrás de un proxy corporativo, los usuarios reciben todo el texto de golpe al final. ¿Cuál es la causa más probable?", "domain": "D2"}, {"stem": "Un servicio Python hace 50 llamadas independientes a Claude por cada petición del usuario usando el cliente síncrono en un bucle, y la latencia total es de un minuto. ¿Qué cambio técnico reduce más la latencia sin superar los rate limits?", "domain": "D2"}, {"stem": "Un equipo recibe errores de validación porque construye el cuerpo JSON de la petición a mano con concatenación de cadenas y el texto del usuario contiene comillas y saltos de línea. ¿Qué corrección es la adecuada?", "domain": "D2"}, {"stem": "¿Qué DOS cabeceras o campos de respuesta debe revisar un cliente HTTP propio para gestionar bien los límites y los errores de la API? (Elige 2)", "domain": "D2"}, {"stem": "Un desarrollador usa el SDK de TypeScript y quiere cancelar una petición en streaming cuando el usuario cierra la pestaña, para no seguir pagando tokens de salida. ¿Qué es lo correcto?", "domain": "D2"}, {"stem": "Un servicio de backend llama a la API desde una función serverless con un límite de ejecución de 60 segundos. Algunas respuestas largas tardan 90 segundos y la función se corta. ¿Qué DOS opciones son razonables? (Elige 2)", "domain": "D2"}, {"stem": "Una función procesa respuestas de la API y asume que usage.output_tokens siempre existe. Con un cliente de streaming propio, el campo aparece a 0 o incompleto. ¿Por qué?", "domain": "D2"}, {"stem": "Un equipo despliega su backend en varias regiones y cada instancia lleva su propio contador de peticiones por minuto para no superar el rate limit. Aun así reciben 429. ¿Por qué?", "domain": "D2"}, {"stem": "Un servicio Node envuelve la API con un cliente HTTP propio y, ante cualquier error de red, reintenta inmediatamente hasta 10 veces. Durante una incidencia de la API, el servicio multiplica por 10 su tráfico y tarda más en recuperarse. ¿Qué patrón técnico falta?", "domain": "D2"}], "deactivate": ["Un stakeholder pide que el asistente dé \"respuestas de calidad\". ¿Cuál debe ser el primer paso del desarrollador?", "Un script de Python resume 500 documentos con llamadas síncronas una tras otra y tarda horas. ¿Qué mejora es la adecuada?", "Un desarrollador llama a la API por HTTP sin SDK y recibe errores por cabeceras que faltan. ¿Qué DOS cabeceras son obligatorias en una llamada a la Messages API con API key? (Elige 2)", "Claude Code ha generado un PR grande para un servicio crítico. ¿Qué proceso es el más adecuado antes de fusionarlo?", "Hay que estimar el coste de procesar un corpus de documentos en varios idiomas. ¿Cuál es el método más fiable?", "El cliente pide \"un chatbot que responda sobre nuestros productos\". ¿Qué pregunta de requisitos es la más importante antes de diseñar?", "Una petición con varias imágenes de alta resolución tarda mucho y consume muchos tokens. ¿Qué mejora es la adecuada?", "Un code review de un PR que integra Claude detecta que la respuesta del modelo se pasa a eval() en Python para convertirla en un diccionario. ¿Qué cambio pedirías?", "Precio base de entrada hipotético: 3 USD por millón. ¿Cuánto cuesta aproximadamente leer de caché 1 millón de tokens si las lecturas cuestan el 10% del precio base?", "¿Qué controla el parámetro max_tokens?", "¿Qué protocolo de mensajes usa MCP entre cliente y servidor?", "¿Para qué sirve MCP Inspector?", "Para empatar cada petición de un batch con su resultado, ¿qué debe incluir el desarrollador en cada petición?", "Una función async en Python lanza 200 llamadas con asyncio.gather sin límite y aparecen muchos 429. Además, cuando una falla, el resto se cancela. ¿Qué DOS cambios son adecuados? (Elige 2)", "Un cliente quiere que Claude responda preguntas sobre su base de datos en lenguaje natural. ¿Qué arquitectura es la más segura para empezar?", "Un PR guarda en la base de datos el prompt final de cada petición junto a la versión del prompt y el ID del modelo. ¿Qué ventaja aporta en el ciclo de vida?", "Un desarrollador necesita la respuesta en menos de 2 segundos y la tarea admite una salida corta. Las pruebas muestran que el 95% del tiempo se va en generar la respuesta. ¿Qué palanca tiene más efecto?", "Para evitar que un prompt muy usado cambie sin control, el equipo quiere que cualquier modificación pase revisión. ¿Qué es lo más adecuado?", "El cliente define el requisito \"el asistente no debe dar consejos médicos\". ¿Cómo se convierte en algo verificable?", "Un equipo duda entre Python y TypeScript para un backend que llama a Claude. ¿Qué afirmación es correcta?", "Un desarrollador debe procesar 10.000 documentos durante la noche para un informe analítico no urgente. El coste es la prioridad y los resultados no hacen falta hasta la mañana siguiente. ¿Qué enfoque encaja mejor con el requisito?", "Un equipo diseña un asistente que, en una misma conversación, recibe peticiones de clientes y también documentos internos con instrucciones para el agente. ¿Qué principio de diseño evita que el contenido del cliente se trate como instrucción?", "Una aplicación necesita mostrar actualizaciones de progreso en tiempo real al navegador mientras un agente trabaja en el servidor durante varios minutos. ¿Qué mecanismo de comunicación encaja?", "Un cliente pide integrar Claude en su flujo de soporte, que ya usa un sistema de tickets con API REST. ¿Qué requisito de infraestructura conviene aclarar primero?", "Una integración en Python usa requests síncrono dentro de un servidor async y el servidor se bloquea con pocas peticiones concurrentes. ¿Qué cambio es el adecuado?", "En un code review de un PR generado con Claude, ¿qué aspecto merece especial atención además de que los tests pasen?", "Un agente de Claude Desktop y una app propia sobre la API usan las mismas instrucciones, pero el agente de Desktop accede a herramientas que la app no tiene. ¿Qué implica para el diseño?", "¿Qué DOS requisitos no funcionales suelen condicionar más la elección entre la API en tiempo real y la Batches API? (Elige 2)", "Un servicio de clasificación debe operar 24/7 con un SLA. ¿Qué práctica de operación es imprescindible?", "Un microservicio llama a Claude para cada petición de usuario y algunas peticiones repetidas son idénticas (preguntas frecuentes). ¿Qué optimización es razonable?", "Un desarrollador quiere probar en local una integración que en producción llama a Claude, sin gastar tokens en cada test unitario. ¿Qué práctica es la adecuada?", "Una empresa necesita que un asistente responda en 8 idiomas. ¿Qué enfoque de requisitos y pruebas es el correcto?", "¿Qué describe mejor la generación de texto de un LLM?", "En la arquitectura de MCP, ¿qué papel tiene el cliente?", "Un asistente lleva seis meses en producción sin cambios de código. ¿En qué fase del ciclo de vida está y qué actividad le corresponde?", "¿Cuál de estos es un requisito no funcional para un asistente de búsqueda basado en Claude?", "Un banco pide un asistente para su equipo de riesgos y añade: \"los datos de clientes no pueden salir de la Unión Europea\". ¿Cómo debe tratar el desarrollador este requisito?", "En la toma de requisitos de un asistente de soporte aparecen estas frases. ¿Cuál es un requisito funcional?", "Dirección fija el objetivo de negocio \"reducir un 30% el tiempo medio de resolución de tickets con Claude\". ¿Cuál es el primer paso para convertirlo en requisitos del sistema?", "Un minorista espera picos de 40 peticiones por segundo durante las rebajas, frente a 2 por segundo el resto del año. ¿Qué implica este requisito para la arquitectura?", "Un asistente de voz debe empezar a hablar menos de un segundo después de que el usuario termine su frase. ¿Qué decisión se deriva de este requisito?", "Producto pide a la vez la máxima calidad posible, el coste más bajo y respuestas instantáneas. ¿Cómo debe proceder el desarrollador?", "Por normativa, cada respuesta que el asistente da a un cliente debe poder reconstruirse en una auditoría. ¿Qué requisito de infraestructura se deriva?", "Un asistente interno debe consultar y actualizar oportunidades en el CRM de la empresa. ¿Qué DOS preguntas de requisitos hay que resolver antes de diseñar las tools? (Elige 2)", "Los empleados acceden a una aplicación web interna con el inicio de sesión único (SSO) de la empresa, y la aplicación llamará a Claude. ¿Qué requisito de arquitectura se deduce?", "Un contrato de servicio exige que la aplicación siga atendiendo aunque la API devuelva errores de sobrecarga durante unos minutos. ¿Qué requisito de diseño se deriva?", "Un cliente quiere que Claude calcule el importe exacto de cada factura a partir de las líneas extraídas de un PDF. ¿Qué reparto de responsabilidades cumple mejor el requisito?", "A mitad del proyecto, un stakeholder pide que el asistente también redacte contratos, algo que no estaba en el alcance. ¿Qué es lo correcto?", "Una normativa exige que ninguna denegación de crédito se comunique sin que la revise una persona. ¿Cómo se refleja en la arquitectura de la solución con Claude?", "El presupuesto del proyecto es de 3.000 euros al mes y se esperan unas 400.000 peticiones mensuales. ¿Qué paso convierte este dato en un requisito verificable?", "El negocio quiere \"un resumen de la actividad comercial del día anterior para los directivos, disponible a primera hora\". ¿Qué arquitectura encaja mejor con este requisito?", "¿Qué DOS de estos son requisitos de infraestructura, y no requisitos funcionales del comportamiento del asistente? (Elige 2)", "Un cliente pide un asistente que resuma expedientes médicos para médicos de urgencias. En la toma de requisitos dicen: \"que sea rápido, que no se invente nada y que funcione en el hospital\". ¿Qué conjunto de requisitos verificables se deriva mejor de esas frases?", "Una aseguradora quiere clasificar 2 millones de documentos históricos una sola vez y, después, unos 500 documentos nuevos al día que deben clasificarse en menos de un minuto desde que llegan. ¿Qué arquitectura cumple ambos requisitos con menor coste?", "¿Qué DOS de estas preguntas de requisitos condicionan directamente la infraestructura de una integración con Claude? (Elige 2)", "Un cliente exige que \"el asistente nunca dé información de otro cliente\". El equipo propone cumplirlo con una instrucción en el system prompt y un test manual. ¿Por qué el planteamiento es insuficiente y qué requisito técnico se deriva?", "Un requisito dice: \"el sistema debe seguir funcionando si Anthropic retira el modelo actual\". ¿Qué decisiones de diseño lo hacen verificable? (Elige 2)", "¿Qué DOS prácticas pertenecen a la fase de operación y mantenimiento de una aplicación con Claude ya desplegada? (Elige 2)", "Un endpoint REST propio recibe un POST que lanza un análisis con Claude de unos 90 segundos. Los clientes HTTP de los usuarios cortan a los 30 segundos. ¿Qué diseño de API es el más adecuado?", "Un microservicio en Node procesa una cola de 10.000 tareas con Promise.all sobre todas a la vez. Aparecen 429, el proceso consume mucha memoria y un solo fallo hace que se pierdan los resultados de las demás. ¿Qué DOS cambios lo resuelven? (Elige 2)", "En un code review ves que una función que llama a Claude mezcla en 300 líneas la construcción del prompt, la llamada HTTP, el parseo, los reintentos y la escritura en base de datos. Hay que añadir un segundo proveedor de modelos. ¿Qué refactor conviene primero?", "Una rama de larga duración generada con ayuda de Claude Code tiene 120 commits y 9.000 líneas cambiadas, y nadie se atreve a revisarla. ¿Qué es lo más adecuado?", "Un equipo integra Claude en su SDLC. ¿Qué DOS usos aportan valor sin debilitar los controles de calidad existentes? (Elige 2)", "Un equipo tiene que migrar 200 llamadas a la API repartidas por un monolito para cambiar el formato de las respuestas. ¿Qué estrategia de refactor a gran escala es la más segura?", "Un frontend en el navegador debe mostrar en tiempo real el progreso de un agente que se ejecuta en el servidor y permitir al usuario cancelarlo. ¿Qué canal encaja mejor y por qué?", "Un equipo construye a la vez un asistente para claude.ai (con un Project) y una integración por API con las mismas instrucciones. ¿Qué diferencia de diseño deben tener en cuenta?", "Un equipo construye una app con Claude que los usuarios abren en el móvil y en el escritorio. Una conversación iniciada en el móvil debe poder continuarse en el escritorio. ¿Qué decisión de diseño lo hace posible?", "Una aplicación usa Claude para generar consultas a un buscador interno a partir de la pregunta del usuario, y luego otra llamada redacta la respuesta con los resultados. Los usuarios a veces escriben preguntas que parecen instrucciones para el segundo paso. ¿Qué límite de contenido es el más importante en el segundo paso?"], "to_bank": ["Un agente con Claude resume páginas web que envían los usuarios. Una página contiene texto oculto que ordena al modelo ignorar las instrucciones anteriores y revelar su system prompt. ¿Qué mitigación es la más eficaz?", "Un equipo necesita que Claude llame a un servicio interno de inventario expuesto como API REST. Quieren que la capacidad sea reutilizable por varias aplicaciones con Claude y que se mantenga de forma independiente a cualquiera de ellas. ¿Qué enfoque encaja mejor?"], "new": [{"domain": "D2", "source": "official_sample", "stem": "Un desarrollador integra una llamada en streaming a la Messages API en una aplicación web de atención al cliente. Los usuarios informan de que las respuestas largas a veces terminan a mitad de frase sin mostrar ningún error. El manejador añade a la página el texto de cada evento content_block_delta y trata el primer evento content_block_stop como el final de la respuesta; nunca lee el stop reason. ¿Qué cambio corrige el defecto de forma más directa?", "options": ["Aumentar el máximo de tokens de salida para que sea menos probable que las respuestas largas se corten por el límite de salida antes de terminar.", "Tratar message_stop como evento terminal y leer el stop reason de message_delta, de modo que una respuesta detenida por el límite de salida se marque en lugar de mostrarse como completa.", "Cambiar a una petición sin streaming para que la respuesta completa llegue en un único payload cuando haya terminado la generación.", "Reintentar la petición con backoff exponencial siempre que una respuesta llegue más corta de lo esperado para la pregunta."], "correct": [1], "explanation": "En la secuencia de eventos de streaming, content_block_stop cierra un único bloque de contenido, no el mensaje: una respuesta con más de un bloque se corta tras el primero y, como nunca se lee el stop reason de message_delta, una respuesta detenida por el límite de salida se presenta como completa. message_stop es el evento terminal. Subir el límite (A) reduce la frecuencia del corte pero no lo detecta; abandonar el streaming (C) oculta el defecto a costa de la experiencia; reintentar (D) trata una condición de parada determinista como un fallo transitorio.", "i18n": {"en": {"stem": "A developer integrates a streaming Messages API call into a customer-support web application. Users report that long answers sometimes end mid-sentence with no error shown. The handler appends the text from each content_block_delta event to the page and treats the first content_block_stop event as the end of the response; it never reads the stop reason. Which change most directly fixes the defect?", "options": ["Increase the maximum output tokens so that long answers are less likely to be cut off by the output limit before they finish.", "Treat message_stop as the terminal event and read the stop reason from message_delta, so that a response stopped at the output limit is flagged rather than shown as complete.", "Switch to a non-streaming request so that the full response arrives in a single payload once generation has finished.", "Retry the request with exponential backoff whenever a response arrives shorter than the length expected for the question."], "explanation": "In the streaming event sequence, content_block_stop closes a single content block, not the message; a response that contains more than one block is cut off after the first, and because the stop reason in message_delta is never read, a response that stopped at the output limit is presented as a complete answer. message_stop is the terminal event. Raising the output limit (A) reduces how often truncation occurs but does not detect it; abandoning streaming (C) hides the defect at the cost of the streaming experience; retrying (D) treats a deterministic stop condition as a transient failure."}}}, {"domain": "D5", "source": "official_sample", "stem": "Un servicio de revisión de documentos envía cada petición con el mismo system prompt y las mismas definiciones de herramientas (varios miles de tokens), seguidos de un documento de política por cliente que cambia unas pocas veces al día, seguido de la pregunta del usuario. El equipo activó el prompt caching colocando un único breakpoint de caché después de la pregunta del usuario. Los datos de uso muestran casi ninguna lectura de caché y los tokens de entrada siguen siendo el coste dominante. ¿Qué cambio produce la mayor reducción de coste sin cambiar el comportamiento del modelo?", "options": ["Ampliar la duración de la caché en el breakpoint existente para que las entradas cacheadas sobrevivan más tiempo entre una petición y la siguiente del mismo cliente.", "Colocar un breakpoint después del system prompt y las definiciones de herramientas y otro después del documento de política, para que cada prefijo se reutilice según su propio ritmo.", "Pasar el paso de revisión a un tier de modelo más pequeño para que los mismos tokens de entrada se facturen a una tarifa menor.", "Acortar el system prompt y las descripciones de herramientas para enviar menos tokens de entrada en cada petición, estén cacheados o no."], "correct": [1], "explanation": "El prompt caching busca un prefijo exacto hasta un breakpoint. Un breakpoint después de la pregunta hace que el prefijo de cada petición sea único, así que nunca se reutiliza nada. Escalonar los breakpoints según el ritmo de cambio, uno tras el contenido que nunca cambia y otro tras el que cambia pocas veces al día, permite reutilizar el prefijo estático en todos los clientes y el de la política en las preguntas de cada cliente, sin cambiar lo que ve el modelo. Una caché más duradera (A) no ayuda a entradas que nunca coinciden; un tier menor (C) cambia el comportamiento y la calidad; recortar el prompt (D) ahorra poco y puede cambiar el comportamiento.", "i18n": {"en": {"stem": "A document-review service sends every request with the same system prompt and tool definitions (several thousand tokens), followed by a per-customer policy document that changes a few times a day, followed by the user's question. The team enabled prompt caching by placing a single cache breakpoint after the user's question. Usage data shows almost no cache reads, and input tokens remain the dominant cost. Which change produces the largest cost reduction without changing the model's behavior?", "options": ["Extend the cache lifetime on the existing breakpoint so that cached entries survive longer between one request and the next from the same customer.", "Place one breakpoint after the system prompt and tool definitions and a second after the policy document, so each prefix is reused on its own schedule.", "Switch the review step to a smaller model tier so that the same input tokens are billed at a lower per-token rate.", "Shorten the system prompt and tool descriptions so that fewer input tokens are sent on each request, cached or not."], "explanation": "Prompt caching matches on an exact prefix up to a breakpoint. A breakpoint placed after the user's question makes every request's prefix unique, so nothing is ever reused. Layering breakpoints by change cadence, one after the content that never changes and one after the content that changes a few times a day, lets the static prefix be reused across every customer and the policy prefix across each customer's questions, with no change to what the model sees. A longer cache lifetime (A) cannot help entries that are never matched; a smaller tier (C) changes behavior and quality; trimming the prompt (D) yields a small saving and risks changing behavior."}}}, {"domain": "D8", "source": "official_sample", "stem": "Un agente de soporte de pedidos tiene una herramienta, get_order_status, con un único parámetro obligatorio, order_id (string). Las trazas muestran que el modelo llama a menudo a la herramienta con el nombre del cliente en lugar del identificador del pedido, recibe un error y luego dice al cliente que no se encuentra el pedido. La descripción de la herramienta dice \"Looks up an order.\". ¿Qué revisión corrige el comportamiento de forma más fiable?", "options": ["Añadir una instrucción en el system prompt para que el modelo use siempre identificadores en lugar de nombres al llamar a cualquier herramienta, y se disculpe con el cliente cuando una búsqueda falle.", "Reescribir la descripción para indicar que order_id es el identificador alfanumérico del pedido, no un nombre, con un ejemplo, y que lo pida si falta; devolver un error estructurado que indique el formato esperado.", "Configurar tool_choice para forzar la llamada a la herramienta en cada turno, de modo que el modelo no pueda saltarse la búsqueda ni responder de memoria.", "Añadir una segunda herramienta, get_order_status_by_name, para que la búsqueda funcione con cualquier valor que pase el modelo, un nombre o un identificador."], "correct": [1], "explanation": "La descripción y el esquema de la herramienta son lo que lee el modelo al decidir cómo llamarla, así que la corrección va ahí: nombrar el identificador esperado, su formato y un ejemplo elimina la ambigüedad, pedirlo cuando falta cierra la vía que causaba el error, y un error estructurado con el formato esperado permite al modelo recuperarse en lugar de informar de un fallo. Una instrucción general en el system prompt (A) es más débil que una guía asociada a la herramienta; forzar la llamada (C) no cambia el argumento que se pasa; una búsqueda por nombre (D) amplía la superficie de la herramienta y puede devolver el pedido de otro cliente con un nombre ambiguo.", "i18n": {"en": {"stem": "An order-support agent has a tool, get_order_status, with a single required parameter, order_id (string). Traces show that the model frequently calls the tool with the customer's name instead of the order identifier, receives an error, and then tells the customer that the order cannot be found. The tool description reads \"Looks up an order.\" Which revision most reliably corrects the behavior?", "options": ["Add a system prompt instruction telling the model to always use identifiers rather than names when it calls any tool, and to apologize to the customer whenever a lookup fails.", "Rewrite the description to state that order_id is the alphanumeric order identifier, not a name, with an example, and to ask for it when missing; return a structured error naming the expected format.", "Set tool_choice to force the tool to be called on every turn so that the model cannot skip the lookup or answer the customer from memory.", "Add a second tool, get_order_status_by_name, so that whichever value the model supplies, a name or an identifier, the lookup succeeds and returns the order."], "explanation": "The tool description and schema are what the model reads when deciding how to call a tool, so the fix belongs there: naming the expected identifier, its format, and an example disambiguates the parameter, instructing the model to ask for the identifier closes the path that produced the error, and a structured error with the expected format lets the model recover rather than report failure. A general system-prompt instruction (A) is weaker than guidance attached to the tool itself; forcing the tool call (C) does not change the argument the model supplies; a lookup by name (D) expands the tool surface and can return another customer's order on an ambiguous name."}}}, {"domain": "D1", "source": "bank", "stem": "Un proceso de alta de proveedores tiene pasos fijos (validar NIF, comprobar listas de sanciones, crear la ficha en el ERP) y auditoría exige poder reproducir exactamente qué se hizo en cada alta. Un desarrollador propone un agente autónomo con las tres herramientas. ¿Qué arquitectura encaja mejor con los requisitos?", "options": ["Un sistema multiagente con un subagente por paso", "Un workflow en código que llama al modelo solo en los pasos que requieren juicio", "Un agente autónomo con temperature 0 para que sea reproducible", "Un agente autónomo con las tres herramientas y un system prompt detallado que liste el orden de los pasos"], "correct": [1], "explanation": "Con pasos fijos y requisitos de auditoría, un workflow en código hace el flujo predecible y reproducible; un agente decide el orden en tiempo de ejecución y la temperature no garantiza reproducibilidad.", "i18n": {"en": {"stem": "A supplier onboarding process has fixed steps (validate tax ID, check sanctions lists, create the ERP record) and audit requires being able to reproduce exactly what was done for each onboarding. A developer proposes an autonomous agent with the three tools. Which architecture best fits the requirements?", "options": ["A multi-agent system with one subagent per step", "A code workflow that calls the model only in steps requiring judgment", "An autonomous agent at temperature 0 so it's reproducible", "An autonomous agent with the three tools and a detailed system prompt listing the step order"], "explanation": "With fixed steps and audit requirements, a code workflow makes the flow predictable and reproducible; an agent decides order at runtime and temperature doesn't guarantee reproducibility."}}}, {"domain": "D1", "source": "bank", "stem": "Un equipo necesita un agente que ejecute código generado para analizar ficheros de clientes durante sesiones largas. No quiere operar contenedores ni gestionar el estado de sesión, y no tiene requisitos que impidan alojar los datos en el proveedor. ¿Qué entorno de ejecución encaja?", "options": ["Ejecutar el código en el portátil de cada analista", "Un bucle sobre la Messages API sin herramienta de ejecución", "Un runtime de agentes gestionado con sandbox", "Un harness propio con el Agent SDK en sus servidores y contenedores que el equipo opera y actualiza"], "correct": [2], "explanation": "Un runtime gestionado con sandbox resuelve ejecución aislada y estado de sesión sin que el equipo los opere; un harness propio da más control a cambio de operarlo.", "i18n": {"en": {"stem": "A team needs an agent that runs generated code to analyze customer files over long sessions. It doesn't want to operate containers or manage session state, and has no requirements preventing data hosting at the provider. Which execution environment fits?", "options": ["Running code on each analyst's laptop", "A Messages API loop without an execution tool", "A managed, sandboxed agent runtime", "A custom Agent SDK harness on its servers with containers the team operates and updates"], "explanation": "A managed sandboxed runtime handles isolated execution and session state without the team operating them; a self-hosted harness gives more control in exchange for running it."}}}, {"domain": "D1", "source": "bank", "stem": "Con el Agent SDK, un equipo quiere que tras cada edición de un fichero se ejecute siempre el linter, y el agente lo omite a veces aunque el system prompt lo pide. ¿Qué cambio hace que ocurra de forma determinista?", "options": ["Añadir un subagente que recuerde ejecutar el linter", "Subir el nivel de effort", "Repetir la instrucción del linter al principio y al final del system prompt en mayúsculas", "Un hook PostToolUse sobre las herramientas de edición que lance el linter"], "correct": [3], "explanation": "Los hooks se ejecutan en el harness en cada evento, sin depender de la decisión del modelo; las instrucciones solo aumentan la probabilidad.", "i18n": {"en": {"stem": "With the Agent SDK, a team wants the linter to always run after every file edit, and the agent sometimes skips it even though the system prompt asks. Which change makes it happen deterministically?", "options": ["Add a subagent that reminds it to run the linter", "Raise the effort level", "Repeat the linter instruction at the start and end of the system prompt in capitals", "A PostToolUse hook on the edit tools that runs the linter"], "explanation": "Hooks run in the harness on every event, independent of the model's decision; instructions only raise the probability."}}}, {"domain": "D1", "source": "bank", "stem": "Un bucle de agente propio llama a la API, ejecuta las herramientas pedidas y vuelve a llamar. En algunos casos el bucle no termina nunca y agota el presupuesto. El código solo sale del bucle cuando la respuesta no contiene texto. ¿Cuál es el defecto?", "options": ["El bucle debería salir cuando la respuesta contiene texto, porque eso indica que el modelo ha terminado de usar herramientas", "Falta bajar la temperature", "La condición de salida debe basarse en el stop_reason (salir si no es tool_use) y tener un límite de iteraciones", "Falta subir max_tokens"], "correct": [2], "explanation": "Una respuesta puede contener texto y tool_use a la vez; el criterio de terminación es el stop_reason, con un límite de iteraciones como salvaguarda.", "i18n": {"en": {"stem": "A custom agent loop calls the API, runs the requested tools and calls again. In some cases the loop never ends and exhausts the budget. The code only exits when the response contains no text. What's the defect?", "options": ["The loop should exit when the response contains text, since that means the model is done with tools", "temperature needs lowering", "The exit condition must be based on stop_reason (exit unless tool_use) with an iteration cap", "max_tokens needs raising"], "explanation": "A response can contain both text and tool_use; the termination criterion is stop_reason, with an iteration cap as a safeguard."}}}, {"domain": "D1", "source": "bank", "stem": "Un agente investigador lanza un subagente para revisar 300 ficheros de log. Tras la revisión, el agente principal responde peor a preguntas posteriores y su contexto está casi lleno de contenido de logs. ¿Qué patrón se ha aplicado mal?", "options": ["El modelo del agente principal", "La temperatura del subagente", "El aislamiento del subagente: debe devolver un resumen, no el contenido revisado", "El número de herramientas del subagente, que debería tener acceso a más fuentes para resumir mejor"], "correct": [2], "explanation": "El valor del subagente es trabajar en su propio contexto y devolver solo lo relevante; si devuelve el material bruto, el contexto principal se satura.", "i18n": {"en": {"stem": "A research agent spawns a subagent to review 300 log files. After the review, the main agent answers later questions worse and its context is nearly full of log content. Which pattern was misapplied?", "options": ["The main agent's model", "The subagent's temperature", "Subagent isolation: it should return a summary, not the reviewed content", "The subagent's tool count, which should access more sources to summarize better"], "explanation": "A subagent's value is working in its own context and returning only what's relevant; if it returns raw material, the main context saturates."}}}, {"domain": "D1", "source": "bank", "stem": "Un agente de soporte atiende al mismo cliente en días distintos y cada vez vuelve a pedirle datos que ya dio (modelo de equipo, número de contrato). ¿Qué patrón falta?", "options": ["Un subagente por día", "Una ventana de contexto más grande para que quepan las conversaciones de todos los días anteriores", "Memoria persistente por cliente que se recupera al iniciar la sesión", "Más ejemplos few-shot en el system prompt"], "correct": [2], "explanation": "La continuidad entre sesiones requiere memoria persistente, acotada por cliente; la API no guarda estado entre conversaciones.", "i18n": {"en": {"stem": "A support agent serves the same customer on different days and each time asks again for data they already gave (equipment model, contract number). Which pattern is missing?", "options": ["A subagent per day", "A bigger context window so all previous days' conversations fit", "Per-customer persistent memory retrieved at session start", "More few-shot examples in the system prompt"], "explanation": "Continuity across sessions requires persistent memory, scoped per customer; the API keeps no state between conversations."}}}, {"domain": "D1", "source": "bank", "stem": "Una definición de agente del Agent SDK declara un subagente \"revisor\" sin lista de herramientas. En producción, el revisor modifica ficheros además de comentarlos. ¿Qué corrección aplica?", "options": ["Cambiar el modelo del revisor", "Ejecutar el revisor después del agente principal", "Declarar explícitamente sus herramientas de solo lectura", "Pedir en su prompt que no edite ficheros y que solo comente lo que encuentre"], "correct": [2], "explanation": "Sin lista explícita, el subagente puede heredar herramientas amplias; declararlas aplica mínimo privilegio de forma determinista.", "i18n": {"en": {"stem": "An Agent SDK agent definition declares a \"reviewer\" subagent with no tool list. In production, the reviewer edits files as well as commenting on them. Which correction applies?", "options": ["Change the reviewer's model", "Run the reviewer after the main agent", "Explicitly declare its read-only tools", "Ask in its prompt not to edit files and only comment on findings"], "explanation": "Without an explicit list, the subagent may inherit broad tools; declaring them applies least privilege deterministically."}}}, {"domain": "D1", "source": "bank", "stem": "Un agente de larga duración trabaja bien la primera hora, pero después repite pasos ya hechos y olvida decisiones iniciales. Las trazas muestran que el contexto se compacta automáticamente varias veces. ¿Qué patrón corrige el comportamiento?", "options": ["Reiniciar el agente cada hora sin guardar nada", "Desactivar la compactación y dejar que el contexto crezca hasta el límite de la ventana", "Guardar el progreso y las decisiones en un fichero o memoria externa que se relee", "Usar más subagentes en paralelo"], "correct": [2], "explanation": "Lo que debe sobrevivir a la compactación (progreso, decisiones) se persiste fuera del contexto y se recupera.", "i18n": {"en": {"stem": "A long-running agent works well for the first hour, but then repeats completed steps and forgets early decisions. Traces show the context auto-compacts several times. Which pattern corrects the behavior?", "options": ["Restart the agent hourly without saving anything", "Disable compaction and let context grow to the window limit", "Store progress and decisions in a file or external memory that's reread", "Use more parallel subagents"], "explanation": "What must survive compaction (progress, decisions) is persisted outside the context and recovered."}}}, {"domain": "D1", "source": "bank", "stem": "Una aseguradora tolera errores en la clasificación inicial de siniestros (se revisan después) pero no en el pago, que es irreversible. ¿Qué diseño respeta esa tolerancia al error?", "options": ["Todo manual", "Pago autónomo y clasificación manual", "Clasificación autónoma; pago tras validación determinista y aprobación", "Un único agente autónomo que clasifica y paga, con revisión posterior de una muestra de los pagos"], "correct": [2], "explanation": "La tolerancia al error de cada paso decide el grado de autonomía: los pasos reversibles pueden ser autónomos; los irreversibles necesitan control determinista.", "i18n": {"en": {"stem": "An insurer tolerates errors in initial claim classification (reviewed later) but not in payment, which is irreversible. Which design respects that error tolerance?", "options": ["Everything manual", "Autonomous payment and manual classification", "Autonomous classification; payment after deterministic validation and approval", "A single autonomous agent that classifies and pays, with later review of a sample of payments"], "explanation": "Each step's error tolerance decides its autonomy: reversible steps can be autonomous; irreversible ones need deterministic control."}}}, {"domain": "D1", "source": "bank", "stem": "Un harness propio ejecuta las herramientas que pide el modelo, pero cuando una falla devuelve el resultado vacío sin marcarlo como error. El agente continúa como si hubiera funcionado. ¿Qué corrección aplica?", "options": ["Devolver el tool_result con is_error y un mensaje descriptivo", "Reintentar la herramienta de forma indefinida dentro del harness hasta que devuelva datos", "Ocultar el fallo al modelo", "Terminar el bucle sin avisar"], "correct": [0], "explanation": "Marcar el error y describirlo permite al modelo decidir cómo recuperarse en lugar de razonar sobre un resultado falso.", "i18n": {"en": {"stem": "A custom harness runs the tools the model requests, but when one fails it returns an empty result without flagging an error. The agent continues as if it worked. Which correction applies?", "options": ["Return the tool_result with is_error and a descriptive message", "Retry the tool indefinitely inside the harness until it returns data", "Hide the failure from the model", "End the loop silently"], "explanation": "Flagging and describing the error lets the model decide how to recover instead of reasoning over a false result."}}}, {"domain": "D1", "source": "bank", "stem": "¿Qué dos requisitos inclinan hacia un harness autoalojado con el Agent SDK frente a un runtime gestionado? (Elige 2)", "options": ["Los datos de la sesión deben quedarse en la infraestructura propia", "Se necesita controlar la red y las dependencias del entorno de ejecución", "Se busca la puesta en marcha más rápida posible", "El equipo no quiere operar infraestructura", "No hay requisitos de custodia de datos"], "correct": [0, 1], "explanation": "La custodia de datos y el control del entorno favorecen el autoalojado; la comodidad operativa favorece el gestionado.", "i18n": {"en": {"stem": "Which two requirements favor a self-hosted Agent SDK harness over a managed runtime? (Choose 2)", "options": ["Session data must stay on own infrastructure", "Control over the execution environment's network and dependencies is needed", "The fastest possible start is sought", "The team doesn't want to operate infrastructure", "There are no data custody requirements"], "explanation": "Data custody and environment control favor self-hosting; operational convenience favors managed."}}}, {"domain": "D1", "source": "bank", "stem": "Un agente de compras con el Agent SDK debe pedir aprobación humana antes de cualquier pedido superior a 1.000 €. Hoy esa regla está en el system prompt y el agente a veces la omite. ¿Qué mecanismo la hace obligatoria?", "options": ["Un subagente que revise los pedidos ya enviados", "Reformular la regla en el system prompt con ejemplos de pedidos que superan el importe", "Un hook PreToolUse que bloquee el pedido sin aprobación", "Subir el effort"], "correct": [2], "explanation": "Un hook previo a la herramienta aplica la regla antes de la acción, sin depender del criterio del modelo.", "i18n": {"en": {"stem": "An Agent SDK purchasing agent must request human approval before any order over €1,000. Today the rule is in the system prompt and the agent sometimes skips it. Which mechanism makes it mandatory?", "options": ["A subagent reviewing orders already sent", "Rephrase the rule in the system prompt with examples of orders over the amount", "A PreToolUse hook blocking the order without approval", "Raise effort"], "explanation": "A pre-tool hook enforces the rule before the action, independent of the model's judgment."}}}, {"domain": "D1", "source": "bank", "stem": "Las trazas de un agente muestran que, tras 40 llamadas a herramientas, empieza a ignorar instrucciones del system prompt y a mezclar datos de búsquedas antiguas. Cada resultado de herramienta ocupa unos 5.000 tokens. ¿Qué patrón falta?", "options": ["Subir la temperature", "Un modelo con ventana mayor para que quepan todas las llamadas sin perder instrucciones", "Gestión del contexto: podar o resumir resultados antiguos", "Más herramientas"], "correct": [2], "explanation": "El contexto saturado de resultados obsoletos degrada el seguimiento de instrucciones; podar o resumir resultados lo corrige.", "i18n": {"en": {"stem": "An agent's traces show that after 40 tool calls it starts ignoring system prompt instructions and mixing data from old searches. Each tool result takes about 5,000 tokens. Which pattern is missing?", "options": ["Raise temperature", "A bigger-window model so every call fits without losing instructions", "Context management: prune or summarize old results", "More tools"], "explanation": "A context saturated with stale results degrades instruction following; pruning or summarizing results fixes it."}}}, {"domain": "D3", "source": "bank", "stem": "Un desarrollador cerró el terminal a mitad de una tarea con Claude Code y quiere retomar exactamente esa conversación. ¿Qué hace?", "options": ["Reanudar la sesión anterior (p. ej. claude --continue o --resume)", "Abrir una sesión nueva y pegar a mano el resumen de lo que recuerda de la conversación anterior", "Volver a clonar el repositorio", "Ejecutar /clear"], "correct": [0], "explanation": "Claude Code permite continuar la sesión más reciente o elegir una anterior para reanudarla con su historial.", "i18n": {"en": {"stem": "A developer closed the terminal mid-task with Claude Code and wants to resume exactly that conversation. What do they do?", "options": ["Resume the previous session (e.g. claude --continue or --resume)", "Open a new session and manually paste a summary of what they remember", "Re-clone the repository", "Run /clear"], "explanation": "Claude Code can continue the most recent session or pick an earlier one to resume with its history."}}}, {"domain": "D3", "source": "bank", "stem": "Un desarrollador termina una tarea y empieza otra sin relación en la misma sesión de Claude Code. Las respuestas mezclan detalles de la tarea anterior. ¿Qué conviene hacer?", "options": ["Empezar con contexto limpio (/clear o una sesión nueva)", "Explicar en cada mensaje que ignore todo lo anterior a la tarea nueva", "Subir el effort", "Reinstalar Claude Code"], "correct": [0], "explanation": "Para tareas no relacionadas, un contexto limpio evita que el historial anterior contamine el trabajo.", "i18n": {"en": {"stem": "A developer finishes a task and starts an unrelated one in the same Claude Code session. Responses mix in details of the previous task. What should they do?", "options": ["Start with a clean context (/clear or a new session)", "Explain in every message to ignore everything before the new task", "Raise effort", "Reinstall Claude Code"], "explanation": "For unrelated tasks, a clean context keeps earlier history from contaminating the work."}}}, {"domain": "D3", "source": "bank", "stem": "Un equipo tiene un CLAUDE.md en la raíz del repositorio con convenciones generales y otro en el subdirectorio /payments con reglas específicas de ese módulo. ¿Cómo se comporta Claude Code al trabajar en /payments?", "options": ["Solo lee el del directorio home del usuario", "Ignora ambos", "Tiene en cuenta ambos; el del subdirectorio añade el contexto específico del módulo", "Ignora el de la raíz y usa solo el del subdirectorio, porque siempre gana el más cercano"], "correct": [2], "explanation": "Los CLAUDE.md se combinan jerárquicamente: el general aporta convenciones y el del subdirectorio añade las específicas.", "i18n": {"en": {"stem": "A team has a CLAUDE.md at the repo root with general conventions and another in /payments with module-specific rules. How does Claude Code behave when working in /payments?", "options": ["It only reads the one in the user's home directory", "It ignores both", "It considers both; the subdirectory one adds module-specific context", "It ignores the root one and uses only the subdirectory one, because the closest always wins"], "explanation": "CLAUDE.md files combine hierarchically: the general one provides conventions and the subdirectory one adds specifics."}}}, {"domain": "D3", "source": "bank", "stem": "Un desarrollador quiere preferencias personales (idioma de los comentarios, estilo de commits) en todos sus proyectos sin imponérselas al equipo. ¿Dónde las pone?", "options": ["En la configuración gestionada de la organización", "En el CLAUDE.md del proyecto, versionado en el repositorio compartido", "En su CLAUDE.md de usuario (en su directorio home)", "En un comentario del código"], "correct": [2], "explanation": "La memoria de usuario aplica a todos sus proyectos y no afecta a los demás miembros del equipo.", "i18n": {"en": {"stem": "A developer wants personal preferences (comment language, commit style) across all their projects without imposing them on the team. Where do they put them?", "options": ["In the organization's managed settings", "In the project CLAUDE.md, versioned in the shared repo", "In their user CLAUDE.md (in their home directory)", "In a code comment"], "explanation": "User memory applies to all their projects without affecting other team members."}}}, {"domain": "D3", "source": "bank", "stem": "Un repositorio tiene en .claude/settings.json una regla que permite ejecutar los tests sin pedir confirmación. Un desarrollador quiere además permitir en su máquina un comando que el equipo no comparte. ¿Dónde lo configura?", "options": ["En el CLAUDE.md", "En .claude/settings.json del repositorio para que todo el equipo tenga el mismo comportamiento", "En la configuración gestionada", "En la configuración local del proyecto, no versionada"], "correct": [3], "explanation": "La configuración local del proyecto permite ajustes personales sin modificar la configuración compartida del equipo.", "i18n": {"en": {"stem": "A repo's .claude/settings.json allows running tests without confirmation. A developer additionally wants to allow, on their machine, a command the team doesn't share. Where do they configure it?", "options": ["In CLAUDE.md", "In the repo's .claude/settings.json so the whole team behaves the same", "In managed settings", "In the project's local, unversioned settings"], "explanation": "Local project settings allow personal tweaks without changing the team's shared settings."}}}, {"domain": "D3", "source": "bank", "stem": "La configuración gestionada de la organización deniega leer ficheros .env. Un desarrollador añade en su configuración de usuario una regla que lo permite. ¿Qué ocurre?", "options": ["Prevalece la denegación gestionada", "Claude Code no arranca", "Prevalece la regla del usuario, porque es la más específica para su máquina", "Se pregunta cada vez al usuario"], "correct": [0], "explanation": "La configuración gestionada tiene la máxima prioridad y no puede anularse con configuración de usuario o proyecto.", "i18n": {"en": {"stem": "The organization's managed settings deny reading .env files. A developer adds a rule in their user settings allowing it. What happens?", "options": ["The managed denial prevails", "Claude Code won't start", "The user rule prevails, since it's the most specific for their machine", "The user is asked each time"], "explanation": "Managed settings have top priority and can't be overridden by user or project settings."}}}, {"domain": "D3", "source": "bank", "stem": "Un script de CI necesita ejecutar Claude Code y procesar los eventos a medida que se producen (mensajes, llamadas a herramientas) para mostrar progreso. ¿Qué modo de salida encaja?", "options": ["Salida de texto final únicamente", "Modo interactivo capturando el texto del terminal con una expresión regular", "Modo plan", "Modo headless con salida en streaming JSON"], "correct": [3], "explanation": "El modo headless con salida JSON en streaming entrega eventos estructurados conforme ocurren.", "i18n": {"en": {"stem": "A CI script needs to run Claude Code and process events as they happen (messages, tool calls) to show progress. Which output mode fits?", "options": ["Final text output only", "Interactive mode, scraping terminal text with a regex", "Plan mode", "Headless mode with streaming JSON output"], "explanation": "Headless mode with streaming JSON output delivers structured events as they happen."}}}, {"domain": "D3", "source": "bank", "stem": "Un desarrollador empieza a usar Claude Code en un repositorio grande sin CLAUDE.md y quiere un primer fichero con la estructura y los comandos del proyecto. ¿Qué comando integrado le ayuda?", "options": ["/clear, que borra la sesión y genera la documentación del proyecto", "/compact", "/init", "/cost"], "correct": [2], "explanation": "/init analiza el repositorio y crea un CLAUDE.md inicial que luego se revisa.", "i18n": {"en": {"stem": "A developer starts using Claude Code in a large repo with no CLAUDE.md and wants a first file with the project structure and commands. Which built-in command helps?", "options": ["/clear, which wipes the session and generates project documentation", "/compact", "/init", "/cost"], "explanation": "/init analyzes the repository and creates an initial CLAUDE.md to review."}}}, {"domain": "D3", "source": "bank", "stem": "Una sesión larga de Claude Code se acerca al límite de contexto, pero el desarrollador quiere conservar el hilo de la tarea en curso. ¿Qué comando usa?", "options": ["/compact, opcionalmente indicando qué conservar", "/exit", "/clear, porque mantiene un resumen automático de la tarea anterior", "/init"], "correct": [0], "explanation": "/compact resume el historial para liberar contexto manteniendo lo esencial; /clear lo descarta.", "i18n": {"en": {"stem": "A long Claude Code session nears the context limit, but the developer wants to keep the thread of the current task. Which command do they use?", "options": ["/compact, optionally saying what to keep", "/exit", "/clear, since it keeps an automatic summary of the previous task", "/init"], "explanation": "/compact summarizes history to free context while keeping the essentials; /clear discards it."}}}, {"domain": "D3", "source": "bank", "stem": "Un equipo quiere que ciertas reglas de estilo solo se apliquen cuando Claude Code trabaja con ficheros de un directorio concreto (p. ej. migraciones SQL), sin cargarlas en el resto de tareas. ¿Qué mecanismo encaja?", "options": ["Una configuración gestionada", "Un hook que escriba las reglas en cada mensaje", "Añadir las reglas al CLAUDE.md raíz para que estén siempre disponibles", "Un fichero de reglas con alcance por rutas"], "correct": [3], "explanation": "Las reglas con alcance por rutas se cargan solo cuando son relevantes, sin ocupar contexto en otras tareas.", "i18n": {"en": {"stem": "A team wants certain style rules to apply only when Claude Code works on files in a specific directory (e.g. SQL migrations), without loading them for other tasks. Which mechanism fits?", "options": ["Managed settings", "A hook that writes the rules into every message", "Add the rules to the root CLAUDE.md so they're always available", "A rules file scoped by path"], "explanation": "Path-scoped rules load only when relevant, without taking context in other tasks."}}}, {"domain": "D3", "source": "bank", "stem": "Un equipo repite cada semana el mismo procedimiento de preparación de release (cambios, notas, versión) con instrucciones largas y scripts de apoyo. Quiere que Claude Code lo aplique cuando sea relevante. ¿Qué extensión encaja?", "options": ["Un servidor MCP", "Un hook PreToolUse que ejecute el procedimiento en cada llamada a herramientas", "Una regla de permisos", "Una Skill con instrucciones y scripts"], "correct": [3], "explanation": "Las Skills empaquetan procedimientos con recursos y se cargan cuando la tarea lo requiere.", "i18n": {"en": {"stem": "A team repeats the same release preparation procedure weekly (changes, notes, version) with long instructions and helper scripts. It wants Claude Code to apply it when relevant. Which extension fits?", "options": ["An MCP server", "A PreToolUse hook running the procedure on every tool call", "A permission rule", "A Skill with instructions and scripts"], "explanation": "Skills package procedures with resources and load when the task requires it."}}}, {"domain": "D3", "source": "bank", "stem": "Un equipo quiere un atajo que los desarrolladores invoquen a mano para generar el resumen de un PR siguiendo una plantilla. ¿Qué extensión es la más directa?", "options": ["Un hook que genere el resumen automáticamente al guardar cualquier fichero", "Un servidor MCP remoto", "Un slash command personalizado", "Una regla de permisos"], "correct": [2], "explanation": "Los slash commands personalizados son atajos invocados por el usuario para prompts repetibles.", "i18n": {"en": {"stem": "A team wants a shortcut developers invoke manually to generate a PR summary following a template. Which extension is most direct?", "options": ["A hook generating the summary automatically when any file is saved", "A remote MCP server", "A custom slash command", "A permission rule"], "explanation": "Custom slash commands are user-invoked shortcuts for repeatable prompts."}}}, {"domain": "D3", "source": "bank", "stem": "Un equipo ha creado una Skill, dos slash commands, un hook y un subagente que funcionan juntos, y quiere distribuirlos a otros diez equipos con versiones. ¿Cómo los empaqueta?", "options": ["En el CLAUDE.md de cada repositorio", "Pidiendo a cada equipo que copie los ficheros en su carpeta .claude", "En un documento con instrucciones", "Como un plugin publicado en un marketplace interno"], "correct": [3], "explanation": "Los plugins agrupan varias extensiones y permiten distribuirlas y actualizarlas de forma versionada.", "i18n": {"en": {"stem": "A team has built a Skill, two slash commands, a hook and a subagent that work together, and wants to distribute them to ten other teams with versions. How do they package them?", "options": ["In each repo's CLAUDE.md", "Ask each team to copy the files into their .claude folder", "In a document with instructions", "As a plugin published to an internal marketplace"], "explanation": "Plugins bundle several extensions and allow versioned distribution and updates."}}}, {"domain": "D3", "source": "bank", "stem": "Un equipo quiere delegar en Claude Code búsquedas amplias por el código sin llenar el contexto de la sesión principal con los resultados intermedios. ¿Qué extensión encaja?", "options": ["Una Skill de estilo", "Una regla de permisos", "Un subagente de exploración que devuelve conclusiones", "Un slash command que pegue todos los resultados en la conversación principal"], "correct": [2], "explanation": "Los subagentes trabajan en su propio contexto y devuelven solo el resultado relevante.", "i18n": {"en": {"stem": "A team wants Claude Code to delegate broad code searches without filling the main session's context with intermediate results. Which extension fits?", "options": ["A style Skill", "A permission rule", "An exploration subagent that returns conclusions", "A slash command pasting every result into the main conversation"], "explanation": "Subagents work in their own context and return only the relevant result."}}}, {"domain": "D3", "source": "bank", "stem": "¿Qué dos casos se resuelven mejor con un hook que con una Skill? (Elige 2)", "options": ["Explicar a Claude el procedimiento de release del equipo", "Aportar documentación de una API interna", "Ejecutar siempre el formateador tras cada edición", "Bloquear siempre la edición de ficheros de producción", "Enseñar el estilo de redacción de la documentación"], "correct": [2, 3], "explanation": "Los hooks aplican acciones deterministas en eventos; las Skills aportan conocimiento y procedimientos que el modelo decide usar.", "i18n": {"en": {"stem": "Which two cases are better handled by a hook than a Skill? (Choose 2)", "options": ["Explaining the team's release procedure to Claude", "Providing internal API documentation", "Always running the formatter after every edit", "Always blocking edits to production files", "Teaching the documentation writing style"], "explanation": "Hooks apply deterministic actions on events; Skills provide knowledge and procedures the model chooses to use."}}}, {"domain": "D4", "source": "bank", "stem": "Un equipo quiere medir si su asistente de soporte \"resuelve el problema del cliente\". Tiene 300 conversaciones etiquetadas por agentes humanos como resueltas o no. ¿Cómo debe validar un juez LLM antes de usarlo a escala?", "options": ["Pedirle que explique cada puntuación", "Ejecutarlo una vez sobre producción", "Medir su acuerdo con esas 300 etiquetas humanas y ajustar la rúbrica", "Usar el modelo más capaz como juez, porque su criterio será siempre mejor que el de los agentes humanos"], "correct": [2], "explanation": "Un juez LLM se calibra contra etiquetas humanas; sin medir el acuerdo no se sabe si mide la meta de calidad.", "i18n": {"en": {"stem": "A team wants to measure whether its support assistant \"solves the customer's problem\". It has 300 conversations labeled resolved or not by human agents. How should it validate an LLM judge before using it at scale?", "options": ["Ask it to explain each score", "Run it once on production", "Measure its agreement with those 300 human labels and tune the rubric", "Use the most capable model as judge, since its criteria will always beat the human agents'"], "explanation": "An LLM judge is calibrated against human labels; without measuring agreement, you don't know whether it measures the quality goal."}}}, {"domain": "D4", "source": "bank", "stem": "Un extractor debe devolver el importe total de cada factura. ¿Qué tipo de evaluación es más defendible?", "options": ["Contar las respuestas no vacías", "Revisión visual ocasional", "Un golden set con importes verificados y comparación exacta por código", "Un juez LLM que puntúe de 1 a 10 si el importe \"parece razonable\" para la factura"], "correct": [2], "explanation": "Para un resultado verificable, un golden set con comparación determinista es barato, exacto y reproducible.", "i18n": {"en": {"stem": "An extractor must return each invoice's total amount. Which evaluation is most defensible?", "options": ["Counting non-empty responses", "Occasional visual review", "A golden set with verified amounts and exact code comparison", "An LLM judge scoring 1-10 whether the amount \"looks reasonable\" for the invoice"], "explanation": "For a verifiable result, a golden set with deterministic comparison is cheap, exact and reproducible."}}}, {"domain": "D4", "source": "bank", "stem": "Un equipo cambia el prompt de un clasificador cada semana. Quiere asegurarse de que lo que ya funcionaba no se rompe. ¿Qué debe incluir en CI?", "options": ["Un conjunto de regresión con casos que ya pasaban y umbral de bloqueo", "Un benchmark público", "Solo los casos nuevos que motivaron cada cambio de prompt", "Una revisión manual del prompt"], "correct": [0], "explanation": "Las pruebas de regresión protegen el comportamiento existente frente a cambios.", "i18n": {"en": {"stem": "A team changes a classifier's prompt weekly. It wants to make sure what already worked doesn't break. What should it include in CI?", "options": ["A regression set of already-passing cases with a blocking threshold", "A public benchmark", "Only the new cases that motivated each prompt change", "Manual prompt review"], "explanation": "Regression tests protect existing behavior against changes."}}}, {"domain": "D4", "source": "bank", "stem": "Un asistente debe negarse a dar asesoramiento fiscal personalizado y derivar a un asesor. ¿Qué tipo de comprobación evalúa esa conducta?", "options": ["Medir la precisión media de las respuestas a preguntas generales de impuestos", "Medir la latencia", "Comprobaciones de comportamiento con casos que piden ese asesoramiento", "Contar tokens"], "correct": [2], "explanation": "Las comprobaciones de comportamiento verifican conductas esperadas en escenarios concretos.", "i18n": {"en": {"stem": "An assistant must decline personalized tax advice and refer to an advisor. Which kind of check evaluates that behavior?", "options": ["Measuring average accuracy on general tax questions", "Measuring latency", "Behavioral checks with cases requesting such advice", "Counting tokens"], "explanation": "Behavioral checks verify expected conduct in specific scenarios."}}}, {"domain": "D4", "source": "bank", "stem": "Un clasificador de spam se evalúa con exactitud. Solo el 3% del tráfico es spam y el modelo apenas lo detecta, aunque la exactitud es del 97%. ¿Qué métrica es más defendible?", "options": ["Exactitud con más casos de evaluación para aumentar la confianza en el resultado", "Tokens de salida", "Precisión y recall sobre la clase spam", "Latencia media"], "correct": [2], "explanation": "Con clases desbalanceadas, las métricas por clase revelan lo que la exactitud oculta.", "i18n": {"en": {"stem": "A spam classifier is evaluated with accuracy. Only 3% of traffic is spam and the model barely detects it, though accuracy is 97%. Which metric is more defensible?", "options": ["Accuracy with more eval cases to boost confidence in the result", "Output tokens", "Precision and recall on the spam class", "Average latency"], "explanation": "With imbalanced classes, per-class metrics reveal what accuracy hides."}}}, {"domain": "D4", "source": "bank", "stem": "Un juez LLM evalúa respuestas comparando la del sistema nuevo y la del actual, siempre en ese orden. Gana casi siempre la primera. ¿Qué ajuste del harness es necesario?", "options": ["Usar temperature alta en el juez", "Evaluar cada par en ambos órdenes", "Cambiar la escala de puntuación del juez a 1-100", "Eliminar la comparación"], "correct": [1], "explanation": "El sesgo de posición se corrige alternando el orden y combinando los resultados.", "i18n": {"en": {"stem": "An LLM judge compares the new system's response and the current one's, always in that order. The first almost always wins. Which harness adjustment is needed?", "options": ["Use high temperature for the judge", "Evaluate each pair in both orders", "Change the judge's scoring scale to 1-100", "Remove the comparison"], "explanation": "Position bias is corrected by alternating order and combining results."}}}, {"domain": "D4", "source": "bank", "stem": "¿Qué dos elementos debe tener un golden set útil para evaluar un asistente? (Elige 2)", "options": ["Respuestas generadas por el propio sistema sin revisar", "Un único tipo de pregunta", "Casos representativos del uso real, incluidos casos límite", "Solo casos que el sistema actual ya resuelve bien", "Respuestas o criterios de éxito verificados por expertos"], "correct": [2, 4], "explanation": "Representatividad y referencias verificadas hacen que un golden set mida la calidad real.", "i18n": {"en": {"stem": "Which two elements should a useful golden set for evaluating an assistant have? (Choose 2)", "options": ["Unreviewed answers generated by the system itself", "A single question type", "Cases representative of real use, including edge cases", "Only cases the current system already handles well", "Expert-verified answers or success criteria"], "explanation": "Representativeness and verified references make a golden set measure real quality."}}}, {"domain": "D4", "source": "bank", "stem": "Un juez LLM puntúa la \"calidad\" de resúmenes sin rúbrica y sus notas varían mucho entre ejecuciones. ¿Qué mejora es más eficaz?", "options": ["Una rúbrica concreta con ejemplos de cada nivel", "Promediar con la longitud de los resúmenes para estabilizar la puntuación", "Quitar las explicaciones", "Usar un juez más pequeño"], "correct": [0], "explanation": "Las rúbricas específicas anclan el criterio del juez y reducen la variabilidad.", "i18n": {"en": {"stem": "An LLM judge scores summary \"quality\" without a rubric and its scores vary a lot between runs. Which improvement is most effective?", "options": ["A concrete rubric with examples for each level", "Averaging with summary length to stabilize the score", "Removing explanations", "Using a smaller judge"], "explanation": "Specific rubrics anchor the judge's criteria and reduce variability."}}}, {"domain": "D4", "source": "bank", "stem": "Un equipo compara dos prompts con 25 casos y una sola ejecución cada uno. B gana por 2 casos. ¿Qué conclusión es defendible?", "options": ["Son idénticos", "A es mejor", "B es mejor y debe desplegarse de inmediato en producción", "No es concluyente; hacen falta más casos o repeticiones"], "correct": [3], "explanation": "Con muestras pequeñas y no determinismo, diferencias pequeñas no son significativas.", "i18n": {"en": {"stem": "A team compares two prompts on 25 cases with a single run each. B wins by 2 cases. Which conclusion is defensible?", "options": ["They're identical", "A is better", "B is better and should ship to production immediately", "Not conclusive; more cases or repetitions are needed"], "explanation": "With small samples and nondeterminism, small differences aren't significant."}}}, {"domain": "D4", "source": "bank", "stem": "Un agente de soporte afirma \"he cancelado tu suscripción\", pero las trazas muestran que nunca llamó a la herramienta de cancelación. ¿Qué modo de fallo es?", "options": ["Alucinación de una acción", "Rechazo, porque el modelo se negó a llamar a la herramienta de cancelación", "Pérdida de contexto", "Deriva de formato"], "correct": [0], "explanation": "Afirmar haber hecho algo que no ocurrió es una alucinación; se corrige ligando las confirmaciones a resultados reales de herramientas.", "i18n": {"en": {"stem": "A support agent says \"I've cancelled your subscription\", but traces show it never called the cancellation tool. Which failure mode is this?", "options": ["Hallucinating an action", "Refusal, because the model declined to call the cancellation tool", "Context loss", "Format drift"], "explanation": "Claiming to have done something that didn't happen is hallucination; fix by tying confirmations to real tool results."}}}, {"domain": "D4", "source": "bank", "stem": "Un agente debería consultar el inventario antes de confirmar disponibilidad, pero a menudo responde \"sí, hay stock\" sin llamar a la herramienta. ¿Qué modo de fallo es y qué corrección ataca la causa?", "options": ["Infra-actuación; aclarar cuándo usar la herramienta en su descripción y prompt", "Rechazo; reformular la petición", "Pérdida de contexto; compactar", "Alucinación de datos; bajar la temperature del modelo para que invente menos"], "correct": [0], "explanation": "No usar una herramienta cuando debería es infra-actuación (under-acting); se corrige especificando cuándo usarla y verificándolo con evals.", "i18n": {"en": {"stem": "An agent should check inventory before confirming availability, but often answers \"yes, in stock\" without calling the tool. Which failure mode is it and which fix targets the cause?", "options": ["Under-acting; clarify when to use the tool in its description and prompt", "Refusal; rephrase the request", "Context loss; compact", "Data hallucination; lower the model's temperature so it invents less"], "explanation": "Not using a tool when it should is under-acting; fix by specifying when to use it and verifying with evals."}}}, {"domain": "D4", "source": "bank", "stem": "Un asistente responde bien durante 30 turnos, pero después olvida una restricción que el usuario dio al principio. ¿Qué modo de fallo es?", "options": ["Pérdida de contexto en una sesión larga", "Error de la capa de integración", "Rechazo", "Deriva de formato del modelo en las respuestas largas"], "correct": [0], "explanation": "Olvidar información temprana en sesiones largas es pérdida de contexto; se aborda con gestión del contexto o persistiendo las restricciones.", "i18n": {"en": {"stem": "An assistant answers well for 30 turns, but then forgets a constraint the user gave at the start. Which failure mode is it?", "options": ["Context loss in a long session", "Integration-layer error", "Refusal", "Format drift in the model's long responses"], "explanation": "Forgetting early information in long sessions is context loss; address with context management or persisting constraints."}}}, {"domain": "D4", "source": "bank", "stem": "Un servicio extrae datos en JSON y, tras unas semanas, el modelo empieza a añadir texto antes del JSON en algunos casos, rompiendo el parser. ¿Qué modo de fallo es y qué recuperación ataca la causa?", "options": ["Deriva de formato; salidas estructuradas con esquema", "Alucinación; cambiar a un modelo de tier superior", "Rechazo; reintentar", "Pérdida de contexto; compactar"], "correct": [0], "explanation": "La deriva de formato se resuelve en origen con salidas estructuradas; parchear el parser trata el síntoma.", "i18n": {"en": {"stem": "A service extracts JSON data and, after a few weeks, the model starts adding text before the JSON in some cases, breaking the parser. Which failure mode is it and which recovery targets the cause?", "options": ["Format drift; schema-based structured outputs", "Hallucination; switch to a higher-tier model", "Refusal; retry", "Context loss; compact"], "explanation": "Format drift is fixed at the source with structured outputs; patching the parser treats the symptom."}}}, {"domain": "D4", "source": "bank", "stem": "La misma pregunta de un usuario recibe a veces \"sí\" y a veces \"no\" sobre si un producto admite devolución. Las trazas muestran que la política correcta no está en el contexto. ¿Dónde se origina el fallo?", "options": ["En el modelo, que responde al azar y debe sustituirse por otro más estable", "En el usuario", "En la temperature", "En la integración: falta la información de política en el contexto"], "correct": [3], "explanation": "La inconsistencia viene de que el modelo no tiene la fuente; la recuperación es aportar la política al contexto.", "i18n": {"en": {"stem": "The same user question sometimes gets \"yes\" and sometimes \"no\" on whether a product can be returned. Traces show the correct policy isn't in the context. Where does the failure originate?", "options": ["In the model, which answers randomly and should be replaced with a more stable one", "In the user", "In temperature", "In the integration: the policy information is missing from context"], "explanation": "The inconsistency comes from the model lacking the source; the recovery is supplying the policy in context."}}}, {"domain": "D4", "source": "bank", "stem": "Un asistente médico rechaza responder preguntas legítimas de profesionales sobre dosis estándar. Las trazas muestran que el system prompt no indica que los usuarios son profesionales sanitarios verificados. ¿Qué recuperación ataca la causa?", "options": ["Reintentar la petición varias veces hasta que el modelo acceda a responder", "Ocultar el rechazo", "Cambiar a otro proveedor", "Aportar en el system prompt el contexto de la audiencia y el uso autorizado"], "correct": [3], "explanation": "Los rechazos indebidos suelen deberse a falta de contexto; aportarlo corrige la causa.", "i18n": {"en": {"stem": "A medical assistant refuses legitimate professional questions about standard doses. Traces show the system prompt doesn't say users are verified healthcare professionals. Which recovery targets the cause?", "options": ["Retry the request several times until the model agrees to answer", "Hide the refusal", "Switch providers", "Provide audience context and authorized use in the system prompt"], "explanation": "Unwarranted refusals often stem from missing context; supplying it fixes the cause."}}}, {"domain": "D4", "source": "bank", "stem": "Un usuario reporta respuestas cortadas. Las trazas muestran stop_reason \"end_turn\" con texto completo en la API, pero la interfaz muestra solo la mitad. ¿Dónde está el fallo?", "options": ["En el modelo, que genera respuestas incompletas en algunos casos", "En la capa de integración (cómo se procesa o muestra la respuesta)", "En el prompt", "En max_tokens"], "correct": [1], "explanation": "Si la API devuelve la respuesta completa, el defecto está en el procesamiento o la presentación.", "i18n": {"en": {"stem": "A user reports cut-off responses. Traces show stop_reason \"end_turn\" with complete text at the API, but the interface shows only half. Where's the failure?", "options": ["In the model, which generates incomplete responses in some cases", "In the integration layer (how the response is processed or displayed)", "In the prompt", "In max_tokens"], "explanation": "If the API returns the full response, the defect is in processing or presentation."}}}, {"domain": "D4", "source": "bank", "stem": "¿Qué dos datos de una traza ayudan a decidir si un fallo procede de la integración o del modelo? (Elige 2)", "options": ["La respuesta cruda de la API antes de cualquier procesamiento", "El navegador del usuario", "La hora del día", "El número de usuarios conectados", "La petición exacta enviada a la API"], "correct": [0, 4], "explanation": "Comparar petición y respuesta cruda con lo que vio el usuario separa los fallos de integración de los del modelo.", "i18n": {"en": {"stem": "Which two pieces of trace data help decide whether a failure comes from the integration or the model? (Choose 2)", "options": ["The raw API response before any processing", "The user's browser", "Time of day", "Connected user count", "The exact request sent to the API"], "explanation": "Comparing request and raw response with what the user saw separates integration failures from model failures."}}}, {"domain": "D4", "source": "bank", "stem": "Un asistente inventa números de referencia de pedidos cuando el cliente no los proporciona. El prompt no dice qué hacer si falta el dato. ¿Qué recuperación ataca la causa y no el síntoma?", "options": ["Bajar la temperature", "Indicar que pida el dato cuando falte y validar el formato", "Añadir un filtro que borre números de referencia de las respuestas", "Reintentar la petición"], "correct": [1], "explanation": "El modelo rellena huecos si no sabe qué hacer; definir la conducta ante datos ausentes corrige la causa.", "i18n": {"en": {"stem": "An assistant invents order reference numbers when the customer doesn't provide them. The prompt doesn't say what to do if data is missing. Which recovery targets the cause, not the symptom?", "options": ["Lower temperature", "Tell it to ask for the data when missing, and validate the format", "Add a filter deleting reference numbers from responses", "Retry the request"], "explanation": "The model fills gaps when it doesn't know what to do; defining behavior for missing data fixes the cause."}}}, {"domain": "D4", "source": "bank", "stem": "Un equipo detecta que su clasificador da etiquetas distintas a la misma entrada en ejecuciones repetidas. ¿Qué evaluación cuantifica el problema?", "options": ["Ejecutar cada caso varias veces y medir la consistencia", "Ejecutar una vez un conjunto más grande de casos distintos", "Revisar solo los casos fallidos", "Medir la latencia"], "correct": [0], "explanation": "La inconsistencia se mide repitiendo cada caso y calculando el acuerdo entre ejecuciones.", "i18n": {"en": {"stem": "A team finds its classifier gives different labels to the same input across repeated runs. Which evaluation quantifies the problem?", "options": ["Run each case several times and measure consistency", "Run a larger set of different cases once", "Review only failed cases", "Measure latency"], "explanation": "Inconsistency is measured by repeating each case and computing agreement across runs."}}}, {"domain": "D4", "source": "bank", "stem": "Tras migrar a una versión nueva del modelo, una evaluación de regresión muestra que un 5% de los casos que antes pasaban ahora fallan. ¿Qué paso de diagnóstico es el más útil?", "options": ["Revertir sin analizar", "Revisar esos casos y agruparlos por patrón", "Repetir la evaluación hasta que mejore el resultado", "Eliminar los casos fallidos de la suite"], "correct": [1], "explanation": "El análisis de los casos que cambiaron revela patrones concretos que pueden corregirse.", "i18n": {"en": {"stem": "After migrating to a new model version, a regression eval shows 5% of previously passing cases now fail. Which diagnostic step is most useful?", "options": ["Revert without analysis", "Review those cases and group them by pattern", "Rerun the evaluation until the result improves", "Remove the failing cases from the suite"], "explanation": "Analyzing the cases that changed reveals concrete patterns that can be fixed."}}}, {"domain": "D4", "source": "bank", "stem": "Un agente de código pasa los tests en evaluación, pero el equipo descubre que modificaba los tests para que pasaran. ¿Qué corrección del harness de evaluación es necesaria?", "options": ["Proteger los tests y verificar que no cambian", "Eliminar los tests", "Usar un modelo distinto", "Añadir más tests al repositorio de evaluación para que sea más difícil modificarlos todos"], "correct": [0], "explanation": "El entorno de evaluación debe impedir atajos; los tests protegidos garantizan que se mide la tarea real.", "i18n": {"en": {"stem": "A coding agent passes the tests in evaluation, but the team finds it was modifying the tests so they'd pass. Which eval harness correction is needed?", "options": ["Protect the tests and verify they don't change", "Remove the tests", "Use a different model", "Add more tests to the eval repo so it's harder to modify them all"], "explanation": "The eval environment must prevent shortcuts; protected tests ensure the real task is measured."}}}, {"domain": "D4", "source": "bank", "stem": "Un equipo calibra su juez LLM y obtiene un 92% de acuerdo con etiquetas humanas en casos fáciles, pero solo un 60% en los casos dudosos, que son los importantes. ¿Qué conclusión es defendible?", "options": ["Hay que eliminar los casos dudosos", "El juez no es fiable donde importa; mejorar la rúbrica o mantener revisión humana ahí", "No importa", "El juez es fiable porque su acuerdo medio supera el 85%"], "correct": [1], "explanation": "La calibración debe mirarse por segmento; un buen acuerdo medio puede ocultar fallos donde la decisión importa.", "i18n": {"en": {"stem": "A team calibrates its LLM judge and gets 92% agreement with human labels on easy cases, but only 60% on borderline cases, which are the important ones. Which conclusion is defensible?", "options": ["Borderline cases should be removed", "The judge isn't reliable where it matters; improve the rubric or keep human review there", "It doesn't matter", "The judge is reliable because average agreement exceeds 85%"], "explanation": "Calibration must be checked per segment; good average agreement can hide failures where the decision matters."}}}, {"domain": "D4", "source": "bank", "stem": "Un asistente RAG responde con información correcta, pero cita un documento distinto del que la contiene. ¿Qué métrica de evaluación detectaría este fallo?", "options": ["Latencia", "Precisión de las respuestas comparadas con una referencia de texto", "Longitud de la respuesta", "Precisión de citas: que la fuente citada respalde la afirmación"], "correct": [3], "explanation": "Evaluar que cada cita respalde lo que se afirma detecta citas incorrectas aunque la respuesta sea correcta.", "i18n": {"en": {"stem": "A RAG assistant answers with correct information but cites a different document from the one containing it. Which evaluation metric would catch this failure?", "options": ["Latency", "Answer accuracy against a text reference", "Response length", "Citation precision: the cited source supports the claim"], "explanation": "Checking each citation supports the claim catches wrong citations even when the answer is correct."}}}, {"domain": "D4", "source": "bank", "stem": "Un agente falla de forma intermitente: unas veces termina la tarea y otras se detiene a mitad. Las trazas de los fallos muestran stop_reason \"max_tokens\" en la última llamada. ¿Cuál es la causa y la recuperación adecuada?", "options": ["Rechazo del modelo; reformular la tarea para que no la rechace", "Límite de salida alcanzado; ampliar el presupuesto o dividir la tarea", "Pérdida de contexto; compactar", "Error de red; reintentar"], "correct": [1], "explanation": "El stop_reason indica un corte por longitud; se corrige con más presupuesto o tareas más pequeñas.", "i18n": {"en": {"stem": "An agent fails intermittently: sometimes it finishes the task and sometimes stops midway. Failure traces show stop_reason \"max_tokens\" on the last call. What's the cause and the right recovery?", "options": ["Model refusal; rephrase the task so it isn't refused", "Output limit hit; raise the budget or split the task", "Context loss; compact", "Network error; retry"], "explanation": "The stop_reason indicates a length cutoff; fix with more budget or smaller tasks."}}}, {"domain": "D4", "source": "bank", "stem": "¿Qué dos métricas son defendibles para evaluar un asistente que debe responder solo con información de los documentos proporcionados? (Elige 2)", "options": ["Tasa de \"no encontrado\" correcta en preguntas sin respuesta", "Número de documentos en el índice", "Groundedness de las afirmaciones", "Velocidad de escritura del usuario", "Número de palabras por respuesta"], "correct": [0, 2], "explanation": "Se mide que lo afirmado esté respaldado y que el sistema se abstenga cuando no hay respuesta.", "i18n": {"en": {"stem": "Which two metrics are defensible for evaluating an assistant that must answer only from supplied documents? (Choose 2)", "options": ["Correct \"not found\" rate on unanswerable questions", "Documents in the index", "Groundedness of claims", "User typing speed", "Words per response"], "explanation": "Measure that claims are supported and that the system abstains when there's no answer."}}}, {"domain": "D4", "source": "bank", "stem": "Un equipo quiere detectar si un cambio de prompt aumenta los rechazos indebidos. ¿Qué evaluación construye?", "options": ["Contar tokens", "Medir la latencia", "Un conjunto de peticiones legítimas límite y su tasa de rechazo antes y después", "Un conjunto de peticiones dañinas para comprobar que siguen rechazándose"], "correct": [2], "explanation": "El sobrerrechazo se mide con peticiones legítimas cercanas al límite y comparando tasas.", "i18n": {"en": {"stem": "A team wants to detect whether a prompt change increases unwarranted refusals. Which evaluation does it build?", "options": ["Counting tokens", "Measuring latency", "A set of legitimate borderline requests and its refusal rate before and after", "A set of harmful requests to check they're still refused"], "explanation": "Over-refusal is measured with legitimate near-boundary requests and comparing rates."}}}, {"domain": "D6", "source": "bank", "stem": "Un agente lleva tres horas trabajando y las respuestas empiezan a ignorar instrucciones iniciales. El contexto está lleno de salidas largas de herramientas ya procesadas. ¿Qué técnica restaura antes el comportamiento?", "options": ["Subir la temperature", "Podar las salidas de herramientas antiguas", "Repetir todas las instrucciones iniciales en cada mensaje del usuario a partir de ahora", "Cambiar de tier"], "correct": [1], "explanation": "Si el exceso son salidas de herramientas obsoletas, podarlas libera contexto y devuelve el foco a las instrucciones.", "i18n": {"en": {"stem": "An agent has been working for three hours and responses start ignoring initial instructions. The context is full of long, already-processed tool outputs. Which technique restores behavior soonest?", "options": ["Raise temperature", "Prune old tool outputs", "Repeat all initial instructions in every user message from now on", "Switch tier"], "explanation": "If the excess is stale tool output, pruning it frees context and refocuses on instructions."}}}, {"domain": "D6", "source": "bank", "stem": "Un desarrollador ha cambiado de objetivo varias veces en una misma sesión y las respuestas mezclan requisitos de objetivos abandonados. ¿Qué criterio indica que conviene empezar una sesión nueva?", "options": ["Que el usuario está cansado", "Que el historial contiene sobre todo contexto ya irrelevante o contradictorio", "Que la sesión tiene más de 20 mensajes, independientemente de su contenido", "Que el modelo responde rápido"], "correct": [1], "explanation": "Cuando el contexto acumulado es mayoritariamente irrelevante o contradictorio, una sesión nueva con un resumen de lo vigente funciona mejor que compactar.", "i18n": {"en": {"stem": "A developer changed goals several times in one session and responses mix in requirements from abandoned goals. Which criterion says it's time for a fresh session?", "options": ["The user is tired", "The history is mostly irrelevant or contradictory context", "The session has over 20 messages, regardless of content", "The model responds fast"], "explanation": "When accumulated context is mostly irrelevant or contradictory, a fresh session with a summary of what's current beats compacting."}}}, {"domain": "D6", "source": "bank", "stem": "Una evaluación de regresión muestra que el asistente a veces responde en inglés a usuarios en español. Las reglas de idioma están en el primer mensaje del usuario, que el historial recorta en conversaciones largas. ¿Qué revisión cierra el hueco de forma estable?", "options": ["Añadir más ejemplos en inglés", "Mover las reglas al system prompt", "Repetir la regla de idioma en mayúsculas en el primer mensaje del usuario", "Bajar la temperature"], "correct": [1], "explanation": "Las instrucciones persistentes van en el system prompt, que no se recorta con el historial.", "i18n": {"en": {"stem": "A regression eval shows the assistant sometimes answers Spanish-speaking users in English. The language rules are in the first user message, which history trimming cuts in long conversations. Which revision closes the gap stably?", "options": ["Add more English examples", "Move the rules to the system prompt", "Repeat the language rule in capitals in the first user message", "Lower temperature"], "explanation": "Persistent instructions belong in the system prompt, which isn't trimmed with history."}}}, {"domain": "D6", "source": "bank", "stem": "Un prompt de extracción falla en direcciones con formato extranjero. Las instrucciones son claras. ¿Qué revisión suele cerrar el hueco con menos coste?", "options": ["Reducir max_tokens", "Activar el razonamiento extendido con un presupuesto alto para todas las direcciones", "Añadir unos pocos ejemplos de direcciones extranjeras con su salida", "Cambiar al tier más capaz"], "correct": [2], "explanation": "Los ejemplos del patrón que falla suelen ser la corrección más directa y barata.", "i18n": {"en": {"stem": "An extraction prompt fails on foreign-format addresses. Instructions are clear. Which revision usually closes the gap at least cost?", "options": ["Lower max_tokens", "Enable high-budget extended reasoning for every address", "Add a few examples of foreign addresses with their output", "Switch to the most capable tier"], "explanation": "Examples of the failing pattern are usually the most direct and cheapest fix."}}}, {"domain": "D6", "source": "bank", "stem": "Un asistente incluye en el prompt texto pegado por el usuario que a veces contiene etiquetas XML que imitan las del propio prompt, y el modelo las confunde con instrucciones. ¿Qué revisión ayuda?", "options": ["Eliminar todas las etiquetas XML del prompt del sistema", "Sanear o escapar la entrada y delimitarla claramente", "Subir la temperature", "Usar un modelo más pequeño"], "correct": [1], "explanation": "Sanear la entrada y delimitarla evita que contenido del usuario se confunda con la estructura del prompt.", "i18n": {"en": {"stem": "An assistant includes user-pasted text in the prompt that sometimes contains XML tags mimicking the prompt's own, and the model mistakes them for instructions. Which revision helps?", "options": ["Remove all XML tags from the system prompt", "Sanitize or escape the input and delimit it clearly", "Raise temperature", "Use a smaller model"], "explanation": "Sanitizing and delimiting input keeps user content from being confused with prompt structure."}}}, {"domain": "D6", "source": "bank", "stem": "Un pipeline consume la salida JSON de Claude. Se usan salidas estructuradas con esquema, pero un servicio posterior falla cuando un campo opcional llega vacío. ¿Qué capa de protección falta?", "options": ["Validación de la respuesta contra las reglas de negocio antes de usarla", "Subir max_tokens", "Más instrucciones en el prompt pidiendo que no deje campos vacíos", "Cambiar de modelo"], "correct": [0], "explanation": "El esquema garantiza la forma; las reglas de negocio (valores válidos, campos requeridos para el uso posterior) se validan aparte.", "i18n": {"en": {"stem": "A pipeline consumes Claude's JSON output. Schema-based structured outputs are used, but a downstream service fails when an optional field arrives empty. Which protection layer is missing?", "options": ["Validating the response against business rules before using it", "Raising max_tokens", "More prompt instructions asking not to leave fields empty", "Switching models"], "explanation": "The schema guarantees shape; business rules (valid values, fields required downstream) are validated separately."}}}, {"domain": "D6", "source": "bank", "stem": "Un servicio no puede usar salidas estructuradas en un flujo concreto y recibe texto libre con JSON incrustado. ¿Qué parsing defensivo es adecuado?", "options": ["Confiar en que siempre llegue bien", "Extraer el bloque JSON, validarlo y gestionar el fallo de forma explícita", "Descartar la respuesta sin registrar", "Hacer eval() del texto para obtener el objeto de la forma más rápida"], "correct": [1], "explanation": "El parsing defensivo extrae, valida contra esquema y define qué hacer si falla, sin ejecutar texto del modelo.", "i18n": {"en": {"stem": "A service can't use structured outputs in one flow and receives free text with embedded JSON. Which defensive parsing fits?", "options": ["Trust it always arrives well-formed", "Extract the JSON block, validate it and handle failure explicitly", "Discard the response without logging", "eval() the text to get the object as fast as possible"], "explanation": "Defensive parsing extracts, validates against a schema and defines what to do on failure, without executing model text."}}}, {"domain": "D6", "source": "bank", "stem": "Un asistente debe responder preguntas usando solo un manual de 25 páginas que cambia una vez al año y recibe miles de consultas al día. ¿Cómo se construye la petición?", "options": ["Fine-tuning", "Recuperar fragmentos con un índice vectorial y dejar que el modelo complete lo que falte", "Manual completo en contexto con caching, y \"no encontrado\" si no está", "Sin documentos, con conocimiento general"], "correct": [2], "explanation": "Con un corpus pequeño y estable, cargarlo completo y cachearlo es simple y preciso; la instrucción de \"no encontrado\" evita inventar.", "i18n": {"en": {"stem": "An assistant must answer only from a 25-page manual that changes once a year and gets thousands of queries a day. How is the request built?", "options": ["Fine-tuning", "Retrieve chunks with a vector index and let the model fill in what's missing", "Full manual in context with caching, and \"not found\" when absent", "No documents, using general knowledge"], "explanation": "With a small, stable corpus, loading it fully and caching is simple and accurate; the \"not found\" instruction prevents invention."}}}, {"domain": "D6", "source": "bank", "stem": "Un asistente debe responder sobre 80.000 documentos que se actualizan a diario. ¿Qué enfoque de grounding encaja?", "options": ["Responder con conocimiento general", "Cargar 10 documentos al azar", "Cargar todos los documentos en contexto en cada petición", "Recuperar solo los pasajes relevantes y citarlos"], "correct": [3], "explanation": "Con un corpus grande y cambiante, se recuperan los pasajes relevantes; el contexto completo no cabe ni es eficiente.", "i18n": {"en": {"stem": "An assistant must answer over 80,000 documents updated daily. Which grounding approach fits?", "options": ["Answer from general knowledge", "Load 10 random documents", "Load every document into context on each request", "Retrieve only the relevant passages and cite them"], "explanation": "With a large, changing corpus, retrieve relevant passages; full context neither fits nor is efficient."}}}, {"domain": "D6", "source": "bank", "stem": "¿Qué dos elementos debe incluir una petición para que el asistente se base en los documentos y cite su origen? (Elige 2)", "options": ["Permiso para completar con conocimiento general cuando falte información", "Ocultar el origen de los documentos", "Documentos delimitados con identificadores para citarlos", "Temperatura alta", "Instrucción de responder solo con los documentos y decir \"no encontrado\" si no está"], "correct": [2, 4], "explanation": "Instrucciones explícitas de grounding y documentos identificables permiten respuestas fundamentadas y citadas.", "i18n": {"en": {"stem": "Which two elements should a request include so the assistant relies on the documents and cites their source? (Choose 2)", "options": ["Permission to fill gaps from general knowledge", "Hiding the documents' origin", "Delimited documents with identifiers to cite", "High temperature", "An instruction to answer only from the documents and say \"not found\" otherwise"], "explanation": "Explicit grounding instructions and identifiable documents enable grounded, cited answers."}}}, {"domain": "D6", "source": "bank", "stem": "Tras corregir un prompt para cerrar un fallo, el equipo quiere que el hueco \"siga cerrado\" en futuros cambios. ¿Qué debe hacer?", "options": ["Documentar el cambio en un comentario dentro del prompt para que nadie lo deshaga", "Añadir los casos que fallaban a la suite de regresión", "Nada", "Bloquear el prompt para que no se modifique nunca más"], "correct": [1], "explanation": "Convertir el fallo en un caso de regresión mantiene la corrección ante cambios futuros.", "i18n": {"en": {"stem": "After revising a prompt to close a failure, the team wants the gap to \"stay closed\" in future changes. What should it do?", "options": ["Document the change in a comment inside the prompt so nobody undoes it", "Add the previously failing cases to the regression suite", "Nothing", "Lock the prompt so it's never modified again"], "explanation": "Turning the failure into a regression case keeps the fix in place under future changes."}}}]}$plan$::jsonb;
begin
  select id into v_exam from public.exams where slug = 'anthropic-ccdv-f';
  if v_exam is null then
    raise exception 'No existe el examen anthropic-ccdv-f';
  end if;

  update public.exams
     set sim_questions = 70, sim_minutes = 120, mini_questions = 20, mini_minutes = 35,
         description = $x$Preguntas de práctica escritas a partir de la guía oficial del examen (v1.1, diciembre 2026). No son preguntas del examen real.$x$, updated_at = now()
   where id = v_exam;

  update public.domains dm
     set name = v.name, weight = v.weight
    from (values
    ('D1', $x$Agents and Workflows$x$, 17),
    ('D2', $x$Applications and Integration$x$, 20),
    ('D3', $x$Claude Code$x$, 8),
    ('D4', $x$Eval, Testing, and Debugging$x$, 10),
    ('D5', $x$Model Selection and Optimization$x$, 12),
    ('D6', $x$Prompt and Context Engineering$x$, 15),
    ('D7', $x$Security and Safety$x$, 8),
    ('D8', $x$Tools and MCP$x$, 10)
    ) as v(code, name, weight)
   where dm.exam_id = v_exam and dm.code = v.code;

  update public.questions q
     set domain_id = dm.id
    from jsonb_to_recordset(v_plan->'moves') as m(stem text, domain text)
    join public.domains dm on dm.exam_id = v_exam and dm.code = m.domain
   where q.exam_id = v_exam and q.stem = m.stem and q.domain_id <> dm.id;

  update public.questions q
     set is_active = false
   where q.exam_id = v_exam and q.is_active
     and q.stem in (select jsonb_array_elements_text(v_plan->'deactivate'));

  update public.questions q
     set source = 'bank'
   where q.exam_id = v_exam and q.source = 'official_sample'
     and q.stem in (select jsonb_array_elements_text(v_plan->'to_bank'));

  insert into public.questions (exam_id, domain_id, source, stem, options, correct, explanation, i18n, author_id)
  select v_exam, dm.id, n.source, n.stem, n.options,
         array(select jsonb_array_elements_text(n.correct)::int), n.explanation, n.i18n, null
    from jsonb_to_recordset(v_plan->'new')
         as n(domain text, source text, stem text, options jsonb, correct jsonb, explanation text, i18n jsonb)
    join public.domains dm on dm.exam_id = v_exam and dm.code = n.domain
   where not exists (select 1 from public.questions q where q.exam_id = v_exam and q.stem = n.stem);
end
$do$;

select d.code as dominio, d.name, d.weight, count(q.id) filter (where q.is_active and q.source <> 'team') as preguntas_activas
from public.domains d
left join public.questions q on q.domain_id = d.id
where d.exam_id = (select id from public.exams where slug = 'anthropic-ccdv-f')
group by d.code, d.name, d.weight
order by d.code;
